const DESTINATIONS=[{id:1,name:'廃都',icon:'♜',label:'THE FALLEN CITY',desc:'灰に覆われた廃都。崩れた街路と封鎖された聖堂を抜け、最深部で待つ灰冠の王を討つ。'},{id:2,name:'屍雪山',icon:'❄',label:'THE CORPSE SNOW MOUNTAIN',statuses:['呪い','凍結'],desc:'雪と死骸に覆われた絶望の山。その頂には死と氷を司る双頭の竜が住んでいる。\n凍てつく冷気は動きを鈍らせ、漂う瘴気は体を呪い生命を蝕む。'}];
DESTINATIONS.push({id:3,name:'海砂漠',icon:'≈',label:'THE SAND SEA',statuses:['激流','砂塵','脱力'],desc:'海が干上がってできた砂漠。子を宿すタツは枯れた海で栄養を求めて彷徨っている。\n流れる砂は徐々に体力を奪い、吹き荒れる砂塵は探索者から視界を奪う。'});
DESTINATIONS.push({id:4,name:'寄生樹海',icon:'♧',label:'THE PARASITIC FOREST',statuses:['芽吹き'],desc:'寄生植物が獣の身体を苗床に広がる樹海。傷口から伸びる芽は、宿主に新たな力を与える。森の奥では、無数の骸を取り込んだ母樹が根を張っている。'});
DESTINATIONS.push({id:5,name:'記憶の書庫',icon:'▤',label:'THE ARCHIVE OF MEMORIES',statuses:['読解','追憶','破綻'],desc:'記憶と記録が積み重なる静かな書庫。幾重もの書架を守る司書と魔導書、その奥で待つ記録の番人を越えよ。'});
DESTINATIONS.push({id:6,name:'瘴気の沼',icon:'≋',label:'THE MIASMA MARSH',statuses:['胞子付着','根絡み'],desc:'毒霧と汚泥に沈む集落。沼に棲む獣たちが、探索者の手札を蝕む。\n花弁の鱗をまとう害獣が、濃い瘴気の奥で開花を待っている。'});
DESTINATIONS.push({id:7,name:'黄金の廃市',icon:'◈',label:'THE GOLDEN RUINS',statuses:['保持ゴールド','貯蔵血','保持エナジー'],desc:'黄金に取り憑かれた者たちが徘徊する廃市。奪われた金も、命も、灯も、敵を倒して取り戻せ。\n献納者が富を注ぐ黄金卿のもとで、強欲は尽きることなく巡る。'});
function destinationUnlocked(id){return id===1||!!S.clearedActs?.includes(id-1);}
function migrateDestinations(){
 S.clearedActs??=[];
 if(S.wins>0&&!S.clearedActs.includes(1))S.clearedActs.push(1);
 for(const h of S.history||[]){
  if(h?.outcome!=='win')continue;
  const act=h.act??1;
  if(DESTINATIONS.some(d=>d.id===act)&&!S.clearedActs.includes(act))S.clearedActs.push(act);
 }
 if(!destinationUnlocked(S.destinationAct)||!DESTINATIONS.some(d=>d.id===S.destinationAct))S.destinationAct=1;
}
migrateDestinations();let destinationPreview=S.destinationAct;
function chosenDestination(){return DESTINATIONS.find(d=>d.id===S.destinationAct)||DESTINATIONS[0];}
function openDestinations(){if(S.run)return;destinationPreview=S.destinationAct;page='destinations';render();}
function selectDestination(id){if(S.run||!DESTINATIONS.some(d=>d.id===id))return;destinationPreview=id;if(destinationUnlocked(id))S.destinationAct=id;render();}
function destinationArt(id){return id===1?art():'<svg viewBox="0 0 700 540" role="img" aria-label="屍雪山の氷の山と双頭の竜"><defs><linearGradient id="snow-sky" x2="0" y2="1"><stop stop-color="#101e2d"/><stop offset="1" stop-color="#516574"/></linearGradient><linearGradient id="snow-mountain" x2="1" y2="1"><stop stop-color="#9aabb0"/><stop offset="1" stop-color="#263a46"/></linearGradient></defs><rect width="700" height="540" fill="url(#snow-sky)"/><circle cx="520" cy="100" r="60" fill="#c2d6d8" opacity=".25"/><path d="M0 470L140 225 225 315 360 90 480 300 565 180 700 430V540H0Z" fill="url(#snow-mountain)"/><path d="M275 234L360 90 433 225 378 198 350 226 326 192Z M100 295L140 225 187 287 147 272Z M515 252L565 180 615 270 561 243Z" fill="#d3dfe0"/><path d="M240 445Q300 310 365 330Q340 242 300 245L272 216 318 215 347 230Q397 271 396 319Q419 259 468 243L490 213 515 223 492 258Q443 282 435 354Q470 380 496 451Z" fill="#172733" stroke="#809ba4" stroke-width="3"/><path d="M290 229L308 231M485 236L499 231" stroke="#9edce7" stroke-width="4"/><path d="M0 472Q200 414 365 473T700 460V540H0Z" fill="#14232d"/><g fill="#b5cbd2" opacity=".6"><circle cx="96" cy="95" r="2"/><circle cx="227" cy="155" r="3"/><circle cx="438" cy="70" r="2"/><circle cx="590" cy="342" r="3"/><circle cx="152" cy="382" r="2"/></g></svg>';}
function destinationRules(d){return d.statuses?.length?'<aside class="destination-rules" aria-label="目的地のステータス効果">'+d.statuses.map(name=>'<section><h3>'+name+'</h3><p>'+({呪い:'付与されている対象は最大HPを失う。攻撃によって呪いを振り払うことができる。',凍結:'ブロックを得るカードのコストが1増加する。防御によって解除できる。'}[name]||keywords[name])+'</p></section>').join('')+'</aside>':'';}
function destinationsScreen(){const d=DESTINATIONS.find(x=>x.id===destinationPreview)||chosenDestination();return '<section class="destination-screen"><div class="section-head"><div><div class="eyebrow">CHOOSE YOUR DESTINATION</div><h1>目的地を選ぶ</h1></div><button onclick="go(&quot;home&quot;)">拠点へ戻る</button></div><div class="destination-layout"><div class="destination-list" role="group" aria-label="目的地">'+DESTINATIONS.map(x=>'<button class="destination-option '+(x.id===d.id?'selected':'')+'" onclick="selectDestination('+x.id+')" aria-pressed="'+(x.id===d.id)+'"><small>ACT '+x.id+'</small><span class="destination-icon">'+x.icon+'</span><strong>'+x.name+'</strong>'+(!destinationUnlocked(x.id)?'<span class="destination-lock">ACT '+(x.id-1)+'クリアで解放</span>':'')+'</button>').join('')+'</div><article class="destination-detail"><div class="destination-summary '+(d.statuses?.length?'has-rules':'')+'">'+destinationRules(d)+'<div class="destination-copy"><div class="eyebrow">ACT '+d.id+' / '+d.label+'</div><h2>'+d.name+'</h2><p>'+d.desc.replace(/\n/g,'<br>')+'</p></div></div><div class="destination-art">'+destinationArt(d.id)+'</div><div class="destination-actions">'+(destinationUnlocked(d.id)?'<span>選択中の目的地</span><button class="primary" onclick="go(&quot;home&quot;)">'+d.name+'に決定 →</button>':'<p>ACT '+(d.id-1)+'をクリアすると探索できます。</p>')+'</div></article></div></section>';}
const homeDestinationBase=home;home=function(){return homeDestinationBase().replace(/<div class="stats">[\s\S]*?<\/div><button class="primary" onclick="start\(\)">/,'<div class="destination-home"><small>目的地</small><button class="destination-home-button" onclick="openDestinations()"><span>ACT '+chosenDestination().id+'　'+chosenDestination().icon+'</span><strong>'+chosenDestination().name+'</strong><span>変更 ›</span></button></div><button class="primary" onclick="start()">');};
const startDestinationBase=start;start=function(){if(!destinationUnlocked(S.destinationAct))return;startDestinationBase();if(S.run){S.run.act=S.destinationAct;render();}};
const finishDestinationBase=finish;finish=function(win,ret=false){const act=S.run?.act||1;if(win&&!S.clearedActs.includes(act))S.clearedActs.push(act);finishDestinationBase(win,ret);if(S.history?.[0])S.history[0].act=act;save();};
const mapDestinationBase=map;map=function(){const d=DESTINATIONS.find(x=>x.id===S.run?.act)||DESTINATIONS[0];return mapDestinationBase().replace('THE FALLEN CITY',d.label+' / ACT '+d.id).replace('廃都の探索路',d.name+'の探索路');};
const renderDestinationBase=render;render=function(){if(globalThis.ASHBOUND_LOADING)return;renderDestinationBase();if(page==='destinations'&&!S.run)$('app').innerHTML=destinationsScreen();};
// Aiming updates only hand descriptions, preserving pointer capture and combat state.
const targetPreviewDescBase=combatDesc;combatDesc=function(c,r){const previous=target,e=previewVulnerableTarget(c,r);let text;try{if(e)target=aimedPreviewEnemy;text=targetPreviewDescBase(c,r);}finally{target=previous;}if(c.characterId!=='hunter'&&e?.vulnerable&&(c.fx.d!=null||c.fx.exactBlock||c.fx.totalPoison||c.fx.equalPoison)){const n=previewDamage(c,r,e),v=hunterAttackDamage(r,e,n);text=text.replace(/(?:<strong class="boost">)?\d+(?:<\/strong>)?ダメージ(?:<\/strong>)?/,'<strong class="boost">'+v+'ダメージ</strong>');}return text;};
function refreshAimedCardText(){if(page!=='battle'||!S.run)return;document.querySelectorAll('.hand .card[data-card]').forEach(el=>{const p=el.querySelector('p');if(p){const previous=target;try{if(aimedPreviewEnemy!=null&&+el.dataset.card===aimedPreviewCard)target=aimedPreviewEnemy;p.innerHTML=rich(combatDesc(combatCard(+el.dataset.card),S.run));}finally{target=previous;}}});}
const targetPreviewAimBase=updateAim;updateAim=function(e){targetPreviewAimBase(e);const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-entity]'),entity=hit?.dataset.entity;const next=drag?.type==='battle'&&entity!=='player'&&S.run?.enemies[+entity]?.hp>0?+entity:null;const id=next!=null?drag.card.id:null;if(next!==aimedPreviewEnemy||id!==aimedPreviewCard){aimedPreviewEnemy=next;aimedPreviewCard=id;refreshAimedCardText();}};
const targetPreviewClearBase=clearDrag;clearDrag=function(){aimedPreviewEnemy=null;aimedPreviewCard=null;targetPreviewClearBase();refreshAimedCardText();};
